  1→//! Deep merge algorithm for YAML configuration values.
  2→//!
  3→//! Bivvy supports configuration layering where later configs override
  4→//! earlier ones. This module implements the merge semantics.
  5→//!
  6→//! # Merge Rules
  7→//!
  8→//! - Objects are merged recursively
  9→//! - Arrays are replaced entirely (not merged)
 10→//! - Null values in overlay delete the corresponding key from base
 11→//! - Scalars in overlay replace scalars in base
 12→
 13→use std::collections::HashSet;
 14→
 15→use serde_yaml::Value;
 16→
 17→/// Deep merge two YAML values.
 18→///
 19→/// Later values override earlier values at the point of conflict.
 20→/// Objects are merged recursively. Arrays are replaced entirely.
 21→/// Null values in overlay delete the corresponding key from base.
 22→///
 23→/// # Arguments
 24→///
 25→/// * `base` - The base configuration
 26→/// * `overlay` - The overlay configuration (takes precedence)
 27→///
 28→/// # Returns
 29→///
 30→/// A new Value with merged contents
 31→pub fn deep_merge(base: &Value, overlay: &Value) -> Value {
 32→    deep_merge_with_leaves(base, overlay, &HashSet::new())
 33→}
 34→
 35→/// Deep merge two YAML values with leaf-key awareness.
 36→///
 37→/// Like `deep_merge`, but keys in `leaf_keys` get special treatment:
 38→/// the MAP at that key is merged (entries added/replaced), but each
 39→/// entry's VALUE replaces entirely instead of recursing. This is used
 40→/// for `environments` blocks where each environment override should
 41→/// replace as a whole rather than being field-merged with the base.
 42→///
 43→/// Null values at the leaf level delete the corresponding entry.
 44→///
 45→/// # Arguments
 46→///
 47→/// * `base` - The base configuration
 48→/// * `overlay` - The overlay configuration (takes precedence)
 49→/// * `leaf_keys` - Keys whose children should replace rather than merge
 50→pub fn deep_merge_with_leaves(base: &Value, overlay: &Value, leaf_keys: &HashSet<&str>) -> Value {
 51→    match (base, overlay) {
 52→        // Both are mappings: merge recursively
 53→        (Value::Mapping(base_map), Value::Mapping(overlay_map)) => {
 54→            let mut result = base_map.clone();
 55→
 56→            for (key, overlay_value) in overlay_map {
 57→                if overlay_value.is_null() {
 58→                    // Null in overlay = delete from result
 59→                    result.remove(key);
 60→                } else if leaf_keys.contains(key.as_str().unwrap_or("")) {
 61→                    // Leaf key: merge the MAP (add/replace entries) but
 62→                    // each entry's VALUE replaces entirely
 63→                    if let (Some(base_inner), Value::Mapping(overlay_inner)) =
 64→                        (result.get(key).and_then(|v| v.as_mapping()), overlay_value)
 65→                    {
 66→                        let mut merged_inner = base_inner.clone();
 67→                        for (inner_key, inner_value) in overlay_inner {
 68→                            if inner_value.is_null() {
 69→                                merged_inner.remove(inner_key);
 70→                            } else {
 71→                                merged_inner.insert(inner_key.clone(), inner_value.clone());
 72→                            }
 73→                        }
 74→                        result.insert(key.clone(), Value::Mapping(merged_inner));
 75→                    } else {
 76→                        result.insert(key.clone(), overlay_value.clone());
 77→                    }
 78→                } else if let Some(base_value) = base_map.get(key) {
 79→                    // Key exists in both: recurse
 80→                    result.insert(
 81→                        key.clone(),
 82→                        deep_merge_with_leaves(base_value, overlay_value, leaf_keys),
 83→                    );
 84→                } else {
 85→                    // Key only in overlay: insert
 86→                    result.insert(key.clone(), overlay_value.clone());
 87→                }
 88→            }
 89→
 90→            Value::Mapping(result)
 91→        }
 92→
 93→        // Overlay is not a mapping, or base is not a mapping: overlay wins
 94→        (_, overlay) => overlay.clone(),
 95→    }
 96→}
 97→
 98→/// Merge multiple configs in order (later overrides earlier).
 99→///
100→/// # Arguments
101→///
102→/// * `configs` - Slice of configs in merge order (first is base, last has highest priority)
103→///
104→/// # Returns
105→///
106→/// A single merged Value
107→pub fn merge_configs(configs: &[Value]) -> Value {
108→    let leaf_keys = HashSet::from(["environments"]);
109→    configs
110→        .iter()
111→        .fold(Value::Mapping(Default::default()), |acc, config| {
112→            deep_merge_with_leaves(&acc, config, &leaf_keys)
113→        })
114→}
115→
116→#[cfg(test)]
117→mod tests {
118→    use super::*;
119→
120→    fn yaml(s: &str) -> Value {
121→        serde_yaml::from_str(s).unwrap()
122→    }
123→
124→    #[test]
125→    fn deep_merge_replaces_at_conflict_point() {
126→        let base = yaml(
127→            r#"
128→steps:
129→  database:
130→    command: "rails db:setup"
131→    watches:
132→      - schema.rb
133→"#,
134→        );
135→        let overlay = yaml(
136→            r#"
137→steps:
138→  database:
139→    command: "rails db:prepare"
140→"#,
141→        );
142→
143→        let result = deep_merge(&base, &overlay);
144→
145→        assert_eq!(result["steps"]["database"]["command"], "rails db:prepare");
146→        // watches should be preserved
147→        assert_eq!(result["steps"]["database"]["watches"][0], "schema.rb");
148→    }
149→
150→    #[test]
151→    fn arrays_are_replaced_not_merged() {
152→        let base = yaml(
153→            r#"
154→watches:
155→  - a.rb
156→  - b.rb
157→"#,
158→        );
159→        let overlay = yaml(
160→            r#"
161→watches:
162→  - c.rb
163→"#,
164→        );
165→
166→        let result = deep_merge(&base, &overlay);
167→        let watches = result["watches"].as_sequence().unwrap();
168→
169→        assert_eq!(watches.len(), 1);
170→        assert_eq!(watches[0], "c.rb");
171→    }
172→
173→    #[test]
174→    fn null_removes_inherited_value() {
175→        let base = yaml(
176→            r#"
177→env:
178→  DEBUG: "true"
179→  LOG: verbose
180→"#,
181→        );
182→        let overlay = yaml(
183→            r#"
184→env:
185→  DEBUG: null
186→"#,
187→        );
188→
189→        let result = deep_merge(&base, &overlay);
190→
191→        assert!(result["env"].get("DEBUG").is_none());
192→        assert_eq!(result["env"]["LOG"], "verbose");
193→    }
194→
195→    #[test]
196→    fn nested_objects_merge_recursively() {
197→        let base = yaml(
198→            r#"
199→settings:
200→  output: verbose
201→  logging: true
202→"#,
203→        );
204→        let overlay = yaml(
205→            r#"
206→settings:
207→  output: quiet
208→"#,
209→        );
210→
211→        let result = deep_merge(&base, &overlay);
212→
213→        assert_eq!(result["settings"]["output"], "quiet");
214→        assert_eq!(result["settings"]["logging"], true);
215→    }
216→
217→    #[test]
218→    fn empty_overlay_returns_base_unchanged() {
219→        let base = yaml(
220→            r#"
221→app_name: Test
222→settings:
223→  output: verbose
224→"#,
225→        );
226→        // Empty YAML file parses to Null, which we want to treat as "no changes"
227→        // So use an empty mapping instead
228→        let overlay = yaml("{}");
229→
230→        let result = deep_merge(&base, &overlay);
231→
232→        assert_eq!(result["app_name"], "Test");
233→        assert_eq!(result["settings"]["output"], "verbose");
234→    }
235→
236→    #[test]
237→    fn merge_configs_merges_multiple_in_order() {
238→        let configs = vec![yaml("a: 1\nb: 2"), yaml("b: 3\nc: 4"), yaml("c: 5")];
239→
240→        let result = merge_configs(&configs);
241→
242→        assert_eq!(result["a"], 1);
243→        assert_eq!(result["b"], 3);
244→        assert_eq!(result["c"], 5);
245→    }
246→
247→    #[test]
248→    fn scalar_overlay_replaces_mapping_base() {
249→        let base = yaml(
250→            r#"
251→settings:
252→  output: verbose
253→"#,
254→        );
255→        let overlay = yaml(
256→            r#"
257→settings: disabled
258→"#,
259→        );
260→
261→        let result = deep_merge(&base, &overlay);
262→        assert_eq!(result["settings"], "disabled");
263→    }
264→
265→    #[test]
266→    fn deeply_nested_merge() {
267→        let base = yaml(
268→            r#"
269→a:
270→  b:
271→    c:
272→      d: 1
273→      e: 2
274→"#,
275→        );
276→        let overlay = yaml(
277→            r#"
278→a:
279→  b:
280→    c:
281→      d: 10
282→"#,
283→        );
284→
285→        let result = deep_merge(&base, &overlay);
286→        assert_eq!(result["a"]["b"]["c"]["d"], 10);
287→        assert_eq!(result["a"]["b"]["c"]["e"], 2);
288→    }
289→
290→    #[test]
291→    fn merge_empty_configs_returns_empty() {
292→        let result = merge_configs(&[]);
293→        assert!(result.as_mapping().unwrap().is_empty());
294→    }
295→
296→    #[test]
297→    fn leaf_key_replaces_entry_values() {
298→        let leaf_keys: HashSet<&str> = ["environments"].iter().copied().collect();
299→
300→        let base = yaml(
301→            r#"
302→steps:
303→  db:
304→    environments:
305→      ci:
306→        command: "pg_isready"
307→        env:
308→          A: "1"
309→"#,
310→        );
311→        let overlay = yaml(
312→            r#"
313→steps:
314→  db:
315→    environments:
316→      ci:
317→        env:
318→          FOO: "1"
319→"#,
320→        );
321→
322→        let result = deep_merge_with_leaves(&base, &overlay, &leaf_keys);
323→
324→        // Overlay's ci block replaces base's entirely
325→        assert!(result["steps"]["db"]["environments"]["ci"]["env"]["FOO"] == "1");
326→        // Base's command should be gone (replaced, not merged)
327→        assert!(result["steps"]["db"]["environments"]["ci"]
