fn update_gitignore(&self, ui: &mut dyn UserInterface) -> Result<()> {
    let gitignore_entries = [".bivvy/config.local.yml", ".bivvy/config.local.toml"];
    let gitignore_path = self.project_root.join(".gitignore");

    if gitignore_path.exists() {
        let mut content = fs::read_to_string(&gitignore_path)?;
        let mut added = false;
        for entry in &gitignore_entries {
            if !content.contains(entry) {
                if !content.ends_with('\n') {
                    content.push('\n');
                }
                content.push_str(entry);
                content.push('\n');
                added = true;
            }
        }
        if added {
            fs::write(&gitignore_path, content)?;
            ui.message("Added .bivvy/config.local.* to .gitignore");
        }
    }

    Ok(())
}
