        fs::write(
            &config_path,
            r#"
app_name: "FullApp"
settings:
  default_output: quiet
steps:
  test:
    command: "echo test"
workflows:
  default:
    steps: [test]
"#,
        )
        .unwrap();

        let config = load_config_file(&config_path).unwrap();
        assert_eq!(config.app_name, Some("FullApp".to_string()));
        assert!(config.steps.contains_key("test"));
        assert!(config.workflows.contains_key("default"));
    }

