//! Configuration file discovery and loading.
//!
//! This module handles finding and loading configuration files from
//! various locations in the correct priority order.

use crate::config::extends::ExtendsResolver;
use crate::config::merger::merge_configs;
use crate::config::schema::BivvyConfig;
use crate::error::{BivvyError, Result};
use std::fs;
use std::path::{Path, PathBuf};

/// Configuration file format, determined by file extension.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConfigFormat {
    /// YAML format (.yml or .yaml extension)
    Yaml,
    /// TOML format (.toml extension)
    Toml,
}

impl ConfigFormat {
    /// Detect format from a file path's extension.
    ///
    /// Returns `None` if the extension is not a recognized config format.
    pub fn from_path(path: &Path) -> Option<Self> {
        match path.extension().and_then(|e| e.to_str()) {
            Some("yml") | Some("yaml") => Some(Self::Yaml),
            Some("toml") => Some(Self::Toml),
            _ => None,
        }
    }
}

/// Convert a TOML value to a serde_yaml::Value for the merge pipeline.
fn toml_to_yaml_value(toml_val: toml::Value, source_path: &Path) -> Result<serde_yaml::Value> {
    serde_yaml::to_value(toml_val).map_err(|e| BivvyError::ConfigParseError {
        path: source_path.to_path_buf(),
        message: format!("Failed to convert TOML to internal format: {}", e),
    })
}

/// Paths to configuration files in priority order (later overrides earlier).
///
/// Merge order:
/// 1. Remote base configs (from `extends:`)
/// 2. User global config (`~/.bivvy/config.yml`)
/// 3. Project config (`.bivvy/config.yml`)
/// 4. Local overrides (`.bivvy/config.local.yml`)
#[derive(Debug, Clone)]
pub struct ConfigPaths {
    /// Remote base config (if extends: is used)
    pub extends: Vec<PathBuf>,

    /// User's global config: ~/.bivvy/config.yml
    pub user_global: Option<PathBuf>,

    /// Project config: .bivvy/config.yml
    pub project: Option<PathBuf>,

    /// Local overrides: .bivvy/config.local.yml
    pub project_local: Option<PathBuf>,
}

impl ConfigPaths {
    /// Discover config files for the given project root.
    ///
    /// Supports both YAML (.yml) and TOML (.toml) formats. Returns an error
    /// if both formats exist for the same config slot (e.g., both config.yml
    /// and config.toml).
    pub fn discover(project_root: &Path) -> Result<Self> {
        Ok(Self {
            extends: Vec::new(), // Populated later after parsing project config
            user_global: Self::find_user_global()?,
            project: Self::find_project_config(project_root)?,
            project_local: Self::find_project_local(project_root)?,
        })
    }

    /// Find a config file, checking for both .yml and .toml variants.
    ///
    /// Returns an error if both exist for the same slot.
    fn find_config_file(dir: &Path, base_name: &str) -> Result<Option<PathBuf>> {
        let yml_path = dir.join(format!("{}.yml", base_name));
        let toml_path = dir.join(format!("{}.toml", base_name));

        let yml_exists = yml_path.exists();
        let toml_exists = toml_path.exists();

        match (yml_exists, toml_exists) {
            (true, true) => Err(BivvyError::ConfigConflict {
                paths: vec![yml_path, toml_path],
            }),
            (true, false) => Ok(Some(yml_path)),
            (false, true) => Ok(Some(toml_path)),
            (false, false) => Ok(None),
        }
    }

    /// Find user's global config at ~/.bivvy/config.{yml,toml}
    fn find_user_global() -> Result<Option<PathBuf>> {
        match dirs::home_dir() {
            Some(home) => Self::find_config_file(&home.join(".bivvy"), "config"),
            None => Ok(None),
        }
    }

    /// Find project config at .bivvy/config.{yml,toml}
    fn find_project_config(project_root: &Path) -> Result<Option<PathBuf>> {
        Self::find_config_file(&project_root.join(".bivvy"), "config")
    }

    /// Find local overrides at .bivvy/config.local.{yml,toml}
    fn find_project_local(project_root: &Path) -> Result<Option<PathBuf>> {
        Self::find_config_file(&project_root.join(".bivvy"), "config.local")
    }

    /// Returns all existing config paths in merge order.
    pub fn all_existing(&self) -> Vec<&PathBuf> {
        let mut paths = Vec::new();

        for p in &self.extends {
            paths.push(p);
        }

        if let Some(p) = &self.user_global {
            paths.push(p);
        }

        if let Some(p) = &self.project {
            paths.push(p);
        }

        if let Some(p) = &self.project_local {
            paths.push(p);
        }

        paths
    }

    /// Check if any project config exists.
    pub fn has_project_config(&self) -> bool {
        self.project.is_some()
    }
}

/// Find the project root by walking up from current directory.
///
/// Looks for:
/// 1. `.bivvy` directory (primary indicator)
/// 2. `.git` directory (fallback)
///
/// # Returns
///
/// The path to the project root, or None if not found.
pub fn find_project_root(start: &Path) -> Option<PathBuf> {
    let mut current = start.to_path_buf();

    loop {
        // Check for .bivvy directory
        if current.join(".bivvy").is_dir() {
            return Some(current);
        }

        // Check for .git directory (fallback)
        if current.join(".git").exists() {
            return Some(current);
        }

        // Move up one directory
        if !current.pop() {
            return None;
        }
    }
}

/// Load a single config file and parse it into BivvyConfig.
///
/// Supports both YAML (.yml/.yaml) and TOML (.toml) formats,
/// detected from the file extension.
///
/// # Errors
///
/// Returns `ConfigNotFound` if the file doesn't exist.
/// Returns `ConfigParseError` if the content is invalid.
pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
    let content = read_config_content(path)?;
    let format = ConfigFormat::from_path(path).unwrap_or(ConfigFormat::Yaml);
    parse_config(&content, path, format)
}

/// Parse config content into BivvyConfig.
///
/// # Arguments
///
/// * `content` - The config file content (YAML or TOML)
/// * `source_path` - Path for error reporting
/// * `format` - The config format to parse as
pub fn parse_config(content: &str, source_path: &Path, format: ConfigFormat) -> Result<BivvyConfig> {
    match format {
        ConfigFormat::Yaml => {
            serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: e.to_string(),
            })
        }
        ConfigFormat::Toml => {
            toml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: e.to_string(),
            })
        }
    }
}

/// Load a config file as raw serde_yaml::Value (for merging).
///
/// Supports both YAML and TOML formats. TOML files are parsed and
/// converted to serde_yaml::Value so they can participate in the
/// standard merge pipeline.
pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
    let content = read_config_content(path)?;
    let format = ConfigFormat::from_path(path).unwrap_or(ConfigFormat::Yaml);

    match format {
        ConfigFormat::Yaml => {
            serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                path: path.to_path_buf(),
                message: e.to_string(),
            })
        }
        ConfigFormat::Toml => {
            let toml_val: toml::Value =
                toml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
                    path: path.to_path_buf(),
                    message: e.to_string(),
                })?;
            toml_to_yaml_value(toml_val, path)
        }
    }
}

/// Read config file content, returning appropriate errors.
fn read_config_content(path: &Path) -> Result<String> {
    fs::read_to_string(path).map_err(|e| {
        if e.kind() == std::io::ErrorKind::NotFound {
            BivvyError::ConfigNotFound {
                path: path.to_path_buf(),
            }
        } else {
            BivvyError::Io(e)
        }
    })
}

/// Load and merge all config files for a project.
///
/// Discovers and merges configs in this order:
/// 1. Remote base configs (from `extends:`)
/// 2. User global config (`~/.bivvy/config.yml`)
/// 3. Project config (`.bivvy/config.yml`)
/// 4. Local overrides (`.bivvy/config.local.yml`)
///
/// # Errors
///
/// Returns `ConfigNotFound` if no project config exists.
/// Returns `ConfigParseError` if any config file is invalid.
pub fn load_merged_config(project_root: &Path) -> Result<BivvyConfig> {
    load_merged_config_with_resolver(project_root, &ExtendsResolver::default())
}

/// Load and merge configs with a specific extends resolver.
///
/// This is the implementation behind `load_merged_config`, exposed
/// separately to allow injecting a custom resolver for testing.
pub fn load_merged_config_with_resolver(
    project_root: &Path,
    resolver: &ExtendsResolver,
) -> Result<BivvyConfig> {
    let paths = ConfigPaths::discover(project_root)?;

    if !paths.has_project_config() {
        return Err(BivvyError::ConfigNotFound {
            path: project_root.join(".bivvy").join("config.yml"),
        });
    }

    let mut configs = Vec::new();

    // Load in merge order
    for path in paths.all_existing() {
        let value = load_config_value(path)?;
        configs.push(value);
    }

    // Merge all configs
    let merged = merge_configs(&configs);

    // Parse merged value into typed config
    let config: BivvyConfig =
        serde_yaml::from_value(merged).map_err(|e| BivvyError::ConfigParseError {
            path: project_root.join(".bivvy").join("config.yml"),
            message: format!("Failed to parse merged config: {}", e),
        })?;

    // Resolve extends if present
    if config.extends.is_some() {
        let resolved = resolver.resolve(&config)?;
        Ok(resolved)
    } else {
        Ok(config)
    }
}

/// Load config with optional path override.
///
/// If `config_override` is provided, loads only that file without merging.
/// Otherwise, discovers and merges all config files.
pub fn load_config(project_root: &Path, config_override: Option<&Path>) -> Result<BivvyConfig> {
    if let Some(override_path) = config_override {
        // Direct load of specified file, no merging
        load_config_file(override_path)
    } else {
        load_merged_config(project_root)
    }
}

